   261→impl FromRecoveredTx<TxEip7702> for TxEnv {
   262→    fn from_recovered_tx(tx: &TxEip7702, caller: Address) -> Self {
   263→        let TxEip7702 {
   264→            chain_id,
   265→            nonce,
   266→            gas_limit,
   267→            to,
   268→            value,
   269→            input,
   270→            max_fee_per_gas,
   271→            max_priority_fee_per_gas,
   272→            access_list,
   273→            authorization_list,
   274→        } = tx;
   275→        Self {
   276→            tx_type: tx.ty(),
   277→            caller,
   278→            gas_limit: *gas_limit,
   279→            gas_price: *max_fee_per_gas,
   280→            kind: TxKind::Call(*to),
   281→            value: *value,
   282→            data: input.clone(),
   283→            nonce: *nonce,
   284→            chain_id: Some(*chain_id),
   285→            gas_priority_fee: Some(*max_priority_fee_per_gas),
   286→            access_list: access_list.clone(),
   287→            authorization_list: authorization_list
   288→                .iter()
   289→                .map(|auth| {
   290→                    Either::Right(RecoveredAuthorization::new_unchecked(
   291→                        auth.inner().clone(),
   292→                        auth.signature()
   293→                            .ok()
   294→                            .and_then(|signature| {
   295→                                secp256k1::recover_signer(&signature, auth.signature_hash()).ok()
   296→                            })
   297→                            .map_or(RecoveredAuthority::Invalid, RecoveredAuthority::Valid),
